import {readFile,writeFile} from 'node:fs/promises';
const port=(await readFile(process.argv[2]+'/DevToolsActivePort','utf8')).split('\n')[0];
const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();const ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let id=0;const map=new Map();ws.onmessage=e=>{let d=JSON.parse(e.data);if(d.id)map.get(d.id)?.(d);};const call=(method,params)=>new Promise(r=>{map.set(++id,r);ws.send(JSON.stringify({id,method,params}));});
const state=await call('Runtime.evaluate',{returnByValue:true,expression:`(()=>{let r=game.state.toyRoomInstance.instance,s=r.battle.state;return {fase:r.arena.state.status,modo:s?.mode,ator:s?.enemy?.actor,estado:s?.enemy?.state,idade:s?.enemy?.elapsed,hp:s?.enemy?.hp,vida:s?.player?.hp,x:r.player.x,ex:s?.enemy?.x,tempo:s?.elapsed,historico:s?.history.slice(-5)}})()`});console.log(JSON.stringify(state.result?.result?.value));const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile('/tmp/legend-video-camera/batalha-atual.png',Buffer.from(shot.result.data,'base64'));ws.close();
